section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/ios-signing-and-provisioning.json",
  "title": "iOS signing and provisioning document",
  "type": "object",
  "required": ["app", "secret_store", "private_keys_outside_secret_store", "certificates", "profiles", "asc_api_keys", "push", "build_configs", "rotation_calendar", "revocation_runbook", "review"],
  "additionalProperties": false,
  "properties": {
    "app": {
      "type": "object",
      "required": ["name", "bundle_id", "built_for_client", "owning_account", "owning_team_id"],
      "properties": {
        "name": {"type": "string", "minLength": 1},
        "bundle_id": {"type": "string", "pattern": "^[A-Za-z0-9.-]+\\.[A-Za-z0-9-]+$"},
        "built_for_client": {"type": "boolean"},
        "owning_account": {"type": "string", "enum": ["client", "agency", "own"]},
        "owning_team_id": {"type": "string", "pattern": "^[A-Z0-9]{10}$"},
        "agency_role_on_client_account": {"type": "string", "enum": ["Admin", "App Manager", "Developer", "Marketing", "Customer Support"]},
        "transfer_plan": {"type": "string", "minLength": 10}
      },
      "if": {"properties": {"built_for_client": {"const": true}}},
      "then": {
        "anyOf": [
          {"properties": {"owning_account": {"const": "client"}}, "required": ["agency_role_on_client_account"]},
          {"properties": {"owning_account": {"const": "agency"}}, "required": ["transfer_plan"]}
        ]
      }
    },
    "secret_store": {
      "type": "object",
      "required": ["kind", "location", "readers"],
      "properties": {
        "kind": {"type": "string", "enum": ["ci_secrets", "fastlane_match", "password_manager"]},
        "location": {"type": "string", "minLength": 3},
        "readers": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 2}}
      }
    },
    "private_keys_outside_secret_store": {"const": false},
    "certificates": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["type", "identifier", "expiry", "storage_location", "shared_by_team"],
        "properties": {
          "type": {"type": "string", "enum": ["development", "distribution", "apns"]},
          "identifier": {"type": "string", "minLength": 4},
          "expiry": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
          "storage_location": {"type": "string", "minLength": 3},
          "shared_by_team": {"type": "boolean"},
          "per_developer_reason": {"type": "string", "minLength": 10}
        },
        "if": {"properties": {"type": {"const": "distribution"}, "shared_by_team": {"const": false}}},
        "then": {"required": ["per_developer_reason"]}
      }
    },
    "profiles": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "bundle_id", "type", "uuid", "expiry", "storage_location"],
        "properties": {
          "name": {"type": "string", "minLength": 1},
          "bundle_id": {"type": "string", "minLength": 3},
          "type": {"type": "string", "enum": ["development", "ad_hoc", "app_store", "enterprise"]},
          "uuid": {"type": "string", "minLength": 8},
          "expiry": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
          "storage_location": {"type": "string", "minLength": 3}
        }
      }
    },
    "asc_api_keys": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["key_id", "issuer_id", "role", "used_by", "p8_storage_location", "p8_stored_at_issue"],
        "properties": {
          "key_id": {"type": "string", "pattern": "^[A-Z0-9]{10}$"},
          "issuer_id": {"type": "string", "minLength": 8},
          "role": {"type": "string", "enum": ["Developer", "App Manager"]},
          "used_by": {"type": "string", "minLength": 2},
          "p8_storage_location": {"type": "string", "minLength": 3},
          "p8_stored_at_issue": {"const": true}
        }
      }
    },
    "push": {
      "type": "object",
      "required": ["auth"],
      "properties": {
        "auth": {"type": "string", "enum": ["token_key", "certificate"]},
        "key_id": {"type": "string", "pattern": "^[A-Z0-9]{10}$"},
        "team_id": {"type": "string", "pattern": "^[A-Z0-9]{10}$"},
        "p8_storage_location": {"type": "string", "minLength": 3},
        "certificate_constraint": {"type": "string", "minLength": 10},
        "certificate_expiry": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}
      },
      "allOf": [
        {"if": {"properties": {"auth": {"const": "token_key"}}}, "then": {"required": ["key_id", "team_id", "p8_storage_location"]}},
        {"if": {"properties": {"auth": {"const": "certificate"}}}, "then": {"required": ["certificate_constraint", "certificate_expiry"]}}
      ]
    },
    "build_configs": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "aps_environment", "apns_host"],
        "properties": {
          "name": {"type": "string", "enum": ["debug", "testflight", "app_store", "ad_hoc", "enterprise"]},
          "aps_environment": {"type": "string", "enum": ["development", "production"]},
          "apns_host": {"type": "string", "enum": ["api.sandbox.push.apple.com", "api.push.apple.com"]}
        },
        "allOf": [
          {"if": {"properties": {"aps_environment": {"const": "development"}}}, "then": {"properties": {"apns_host": {"const": "api.sandbox.push.apple.com"}}}},
          {"if": {"properties": {"aps_environment": {"const": "production"}}}, "then": {"properties": {"apns_host": {"const": "api.push.apple.com"}}}}
        ]
      }
    },
    "rotation_calendar": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["asset", "expiry", "rotate_by", "lead_days", "owner"],
        "properties": {
          "asset": {"type": "string", "minLength": 4},
          "expiry": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
          "rotate_by": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
          "lead_days": {"type": "integer", "minimum": 30},
          "owner": {"type": "string", "minLength": 3}
        }
      }
    },
    "revocation_runbook": {
      "type": "object",
      "required": ["who_may_revoke", "impact", "regeneration_order", "verified_against"],
      "properties": {
        "who_may_revoke": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 3}},
        "impact": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["certificate_type", "installed_builds", "pipelines_broken"],
            "properties": {
              "certificate_type": {"type": "string", "enum": ["development", "distribution_app_store", "distribution_ad_hoc", "distribution_enterprise", "apns"]},
              "installed_builds": {"type": "string", "enum": ["keep_launching", "stop_launching", "not_applicable"]},
              "pipelines_broken": {"type": "array", "items": {"type": "string"}}
            }
          }
        },
        "regeneration_order": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 3}},
        "verified_against": {"type": "string", "pattern": "^https://developer\\.apple\\.com/"}
      }
    },
    "review": {
      "type": "object",
      "required": ["status", "binding_action_performed_by_agent"],
      "properties": {
        "status": {"type": "string", "enum": ["draft", "ready_for_review", "approved"]},
        "reviewer": {"type": "string", "minLength": 3},
        "approved_on": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
        "binding_action_performed_by_agent": {"const": false}
      },
      "if": {"properties": {"status": {"const": "approved"}}},
      "then": {"required": ["reviewer", "approved_on"]}
    }
  }
}

example.code:
{
  "app": {"name": "Northwind Field", "bundle_id": "com.northwind.field", "built_for_client": true, "owning_account": "client", "owning_team_id": "A1B2C3D4E5", "agency_role_on_client_account": "App Manager"},
  "secret_store": {"kind": "fastlane_match", "location": "git@github.com:northwind/ios-certificates.git (match, encrypted)", "readers": ["ci:github-actions/northwind-field", "maria@agency.example", "release-lead@northwind.example"]},
  "private_keys_outside_secret_store": false,
  "certificates": [
    {"type": "distribution", "identifier": "Apple Distribution: Northwind Ltd (A1B2C3D4E5), serial 6F3A9C2E", "expiry": "2027-02-14", "storage_location": "match: certs/distribution/6F3A9C2E.p12", "shared_by_team": true},
    {"type": "development", "identifier": "Apple Development: CI (A1B2C3D4E5), serial 1D8B44A0", "expiry": "2027-02-14", "storage_location": "match: certs/development/1D8B44A0.p12", "shared_by_team": true}
  ],
  "profiles": [
    {"name": "match AppStore com.northwind.field", "bundle_id": "com.northwind.field", "type": "app_store", "uuid": "c4d1a2e6-7f3b-4a9c-9d2e-0b1f5a6c7d8e", "expiry": "2027-02-14", "storage_location": "match: profiles/appstore/"},
    {"name": "match Development com.northwind.field", "bundle_id": "com.northwind.field", "type": "development", "uuid": "9a8b7c6d-5e4f-4a3b-8c2d-1e0f9a8b7c6d", "expiry": "2027-02-14", "storage_location": "match: profiles/development/"}
  ],
  "asc_api_keys": [
    {"key_id": "K7M2P9Q4RS", "issuer_id": "69a6de8e-1234-47e3-e053-5b8c7c11a4d1", "role": "App Manager", "used_by": "github-actions/northwind-field upload-testflight", "p8_storage_location": "GitHub Actions secret ASC_KEY_P8 (org: northwind)", "p8_stored_at_issue": true}
  ],
  "push": {"auth": "token_key", "key_id": "T3N8V5W2XY", "team_id": "A1B2C3D4E5", "p8_storage_location": "backend vault: secret/apns/northwind-field.p8"},
  "build_configs": [
    {"name": "debug", "aps_environment": "development", "apns_host": "api.sandbox.push.apple.com"},
    {"name": "testflight", "aps_environment": "production", "apns_host": "api.push.apple.com"},
    {"name": "app_store", "aps_environment": "production", "apns_host": "api.push.apple.com"}
  ],
  "rotation_calendar": [
    {"asset": "Apple Distribution serial 6F3A9C2E", "expiry": "2027-02-14", "rotate_by": "2027-01-10", "lead_days": 35, "owner": "maria@agency.example"},
    {"asset": "Apple Development serial 1D8B44A0", "expiry": "2027-02-14", "rotate_by": "2027-01-10", "lead_days": 35, "owner": "maria@agency.example"},
    {"asset": "profile c4d1a2e6 (App Store)", "expiry": "2027-02-14", "rotate_by": "2027-01-10", "lead_days": 35, "owner": "maria@agency.example"},
    {"asset": "profile 9a8b7c6d (Development)", "expiry": "2027-02-14", "rotate_by": "2027-01-10", "lead_days": 35, "owner": "maria@agency.example"}
  ],
  "revocation_runbook": {
    "who_may_revoke": ["release-lead@northwind.example", "maria@agency.example"],
    "impact": [
      {"certificate_type": "distribution_app_store", "installed_builds": "keep_launching", "pipelines_broken": ["github-actions/northwind-field release"]},
      {"certificate_type": "development", "installed_builds": "stop_launching", "pipelines_broken": ["github-actions/northwind-field pr-build"]},
      {"certificate_type": "apns", "installed_builds": "not_applicable", "pipelines_broken": ["backend push sender"]}
    ],
    "regeneration_order": ["revoke in the portal", "fastlane match nuke <type> then match <type>", "regenerate profiles for the bundle id", "rotate CI secrets", "run a TestFlight build and a push smoke test"],
    "verified_against": "https://developer.apple.com/help/account/certificates/revoke-a-certificate/"
  },
  "review": {"status": "ready_for_review", "reviewer": "release-lead@northwind.example", "binding_action_performed_by_agent": false}
}

